<?php
namespace App\Domain\WorkProcesses; use App\Models\{WorkProcess,Industry,Page,Product,Solution}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException; final class WorkProcessRelationManager { public function sync(WorkProcess $process,array $solutions,array $products,array $industries,array $pages):void{foreach([[$solutions,8],[$products,8],[$industries,8],[$pages,6]] as [$ids,$max])if(count($ids)!==count(array_unique($ids))||count($ids)>$max)throw ValidationException::withMessages(['relations'=>'Relations must be unique and within their configured limit.']);if(Solution::whereIn('id',$solutions)->whereNotNull('archived_at')->exists()||Product::whereIn('id',$products)->whereNotNull('archived_at')->exists()||Industry::whereIn('id',$industries)->whereNotNull('archived_at')->exists()||Page::whereIn('id',$pages)->whereNotNull('archived_at')->exists())throw ValidationException::withMessages(['relations'=>'Archived targets cannot be selected.']);DB::transaction(function()use($process,$solutions,$products,$industries,$pages){foreach([['relatedSolutions',$solutions],['relatedProducts',$products],['relatedIndustries',$industries],['relatedPages',$pages]] as [$relation,$ids])$process->{$relation}()->sync(collect($ids)->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i+1]])->all());});WorkProcessCache::forget($process->id);} }
